-- backfill from the rows already there (unless the tree was kept)
DO $b$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_temp.authz_kept WHERE name = 'team__parent__tree') THEN
    PERFORM authz_int."team__parent__tree_rebuild"();
  END IF;
END $b$;

-- team__parent__tree was built beside the one in use, from a snapshot: what changed since is done again
DO $authz_catch_up$
DECLARE v authz_int.next_trees;
BEGIN
  SELECT * INTO v FROM authz_int.next_trees WHERE name = 'team__parent__tree';
  IF v.name IS NULL OR NOT EXISTS (SELECT 1 FROM pg_temp.authz_kept WHERE name = 'team__parent__tree') THEN
    RAISE EXCEPTION 'rowstile: team__parent__tree was not built beside the one in use (the migration before this one does that) [AZ608]';
  END IF;
  IF coalesce((SELECT s.value::bigint FROM authz.settings s WHERE s.key = 'changes_trimmed_to'), 0) > v.feed
     OR (SELECT s.value::bigint FROM authz.settings s WHERE s.key = 'changes_trimmed_txid')
        >= pg_catalog.pg_snapshot_xmin(v.snap)::text::bigint
     OR EXISTS (SELECT 1 FROM authz.changes c WHERE c.object_type = 'team' AND '*' = ANY (c.object_ids)
                AND c.cause <> 'dependent'
                AND NOT pg_catalog.pg_visible_in_snapshot(c.txid::text::xid8, v.snap)) THEN
    PERFORM authz_int."team__parent__tree_rebuild"();          -- the feed doesn't say everything that changed since: all of it
  ELSE
    PERFORM authz_int."team__parent__tree_refresh"(ARRAY(SELECT x."id" FROM "hd"."teams" x WHERE NOT pg_catalog.pg_visible_in_snapshot(((((pg_catalog.pg_current_xact_id()::text::bigint >> 32) - CASE WHEN x.xmin::text::bigint > (pg_catalog.pg_current_xact_id()::text::bigint & 4294967295) THEN 1 ELSE 0 END) << 32) | x.xmin::text::bigint)::text::xid8, v.snap)
      UNION SELECT y::uuid FROM authz.changes c, unnest(c.object_ids) y
      WHERE c.object_type = 'team' AND c.cause <> 'dependent'
        AND c.txid >= pg_catalog.pg_snapshot_xmin(v.snap)::text::bigint
        AND NOT pg_catalog.pg_visible_in_snapshot(c.txid::text::xid8, v.snap) AND y <> '*'));
    -- rows deleted since
    DELETE FROM authz_int."team__parent__tree" d WHERE NOT EXISTS (SELECT 1 FROM "hd"."teams" x WHERE x."id" = d.descendant)
                             OR NOT EXISTS (SELECT 1 FROM "hd"."teams" x WHERE x."id" = d.ancestor);
  END IF;
  DELETE FROM authz_int.next_trees WHERE name = 'team__parent__tree';
END $authz_catch_up$;

