CREATE OR REPLACE VIEW authz_int."team__oversee" AS
  SELECT c.descendant AS id FROM authz_int."team__parent__tree" c
  WHERE c.ancestor IN (SELECT s.id FROM authz_int."team__oversee__start"() s(id));

