LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  (SELECT g.subject_id::uuid FROM authz.shares g WHERE g.object_type = 'ticket' AND g.object_id = ($1)::text AND g.relation = ANY ((SELECT authz_int.role_relations('ticket', 'work'))::text[]) AND EXISTS (SELECT 1 FROM authz.roles ro WHERE 'role:' || ro.id = g.relation AND ro.owner_type = 'workspace' AND ro.owner_id IN (SELECT (w."workspace_id")::text FROM "hd"."tickets" w WHERE w."id" = $1)) AND g.subject_type = 'user' AND g.subject_relation = '' AND g.subject_id <> '*')
